// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {keepMyEther} from "../src/keepMyEther.sol";

contract InvMutTest is Test {
    keepMyEther c;
    function setUp() public { c = new keepMyEther(); }
    function testFuzz_property(uint256 amount, address actor) public {
        vm.assume(actor != address(0));
        vm.assume(actor != address(c));
        bound(amount, 1, type(uint96).max);

        vm.deal(actor, amount);
        vm.prank(actor);
        (bool depositOk, ) = address(c).call{value: amount}("");
        require(depositOk, "deposit failed");

        vm.prank(actor);
        (bool withdrawOk, ) = address(c).call(abi.encodeWithSignature("withdraw()"));

        assertTrue(c.balances(actor) == 0);
    }
}
